/* Pure, deterministic animation curves. All times are seconds within the chess scene. */
export const clip=v=>Math.max(0,Math.min(1,v));
export function easing(v,type='smooth'){v=clip(v);return type==='linear'?v:type==='hold'?(v>=1?1:0):type==='in'?v*v:type==='out'?1-(1-v)*(1-v):v*v*(3-2*v)}
export function pose(position=[0,0,0],rotation=[0,0,0],scale=[1,1,1],visible=true){return {position:[...position],rotation:[...rotation],scale:[...scale],visible}}
export function key(time,position,rotation=[0,0,0],visible=true,ease='smooth'){return {time,...pose(position,rotation,[1,1,1],visible),ease}}
export function sampleTrack(track,time,fallback=pose()){if(!track||track.enabled===false||!track.keys?.length)return structuredClone(fallback);const keys=[...track.keys].sort((a,b)=>a.time-b.time),t=(time-(track.offset||0))*(track.speed||1);let a=keys[0],b=keys[0];if(t>=keys.at(-1).time)return structuredClone(keys.at(-1));if(t<=a.time)return structuredClone(a);for(let i=1;i<keys.length;i++)if(t<=keys[i].time){a=keys[i-1];b=keys[i];break}const q=easing((t-a.time)/Math.max(.001,b.time-a.time),b.ease),out={visible:t<b.time?a.visible!==false:b.visible!==false};for(const p of ['position','rotation','scale'])out[p]=(a[p]||fallback[p]).map((v,i)=>v+((b[p]||fallback[p])[i]-v)*q);return out}
export function defaultTracks(fx={}){const spin=fx.chessSpin??70,start=fx.chessMove??5,second=fx.chessSecond??10,duration=fx.chessMoveTime??3;return {
 'b-pawn-3':{enabled:true,keys:[key(0,[-.5,0,2.5]),key(start,[-.5,0,2.5]),key(start+duration,[-.5,0,1.5],[0,spin,0]),key(27.5,[-.5,0,1.5],[0,spin,0]),key(28.8,[-1.25,.16,2.25],[0,100,92]),key(30,[-2,.1,3],[0,120,92],false)]},
 'w-pawn-5':{enabled:true,keys:[key(0,[1.5,0,-2.5]),key(second,[1.5,0,-2.5]),key(second+duration,[1.5,0,-1.5],[0,-spin,0])]},
 'b-knight-6':{enabled:true,keys:[key(0,[2.5,0,3.5]),key(17,[2.5,0,3.5]),key(19,[2.5,1.9,3.5],[0,180,0]),key(21,[1.5,1.6,1.5],[0,540,0]),key(23,[1.5,0,1.5],[0,720,0]),key(29.5,[1.5,0,1.5],[0,720,0]),key(31,[1.5,1.8,1.5],[180,900,0]),key(33,[1.5,0,1.5],[360,1080,0])]},
 'w-pawn-3':{enabled:true,keys:[key(0,[-.5,0,-2.5]),key(25,[-.5,0,-2.5]),key(28,[-.5,0,1.5],[0,180,0])]},
 'w-knight-1':{enabled:true,keys:[key(0,[-2.5,0,-3.5]),key(33.5,[-2.5,0,-3.5]),key(35,[-2.5,1.8,-3.5],[0,-180,0]),key(37,[-1.5,1.3,-1.5],[0,-540,0]),key(38.5,[-1.5,0,-1.5],[0,-720,0])]},
 'b-bishop-5':{enabled:true,keys:[key(0,[1.5,0,3.5]),key(40,[1.5,0,3.5]),key(43,[-.8,1.1,-2.8],[0,120,0]),key(48,[-.8,3,-2.8],[0,360,0])]}
}}
export function sampleCamera(age,fx){const custom=fx.chessCameraKeys;if(custom?.length){const keys=[...custom].sort((a,b)=>a.time-b.time);let a=keys[0],b=a;if(age>=keys.at(-1).time)a=b=keys.at(-1);else for(let i=1;i<keys.length;i++)if(age<=keys[i].time){a=keys[i-1];b=keys[i];break}const q=easing((age-a.time)/Math.max(.001,b.time-a.time),b.ease);return {position:a.position.map((v,i)=>v+(b.position[i]-v)*q),target:a.target.map((v,i)=>v+(b.target[i]-v)*q),fov:(a.fov||38)+((b.fov||38)-(a.fov||38))*q}}
 const pull=easing(age/fx.chessPull),orbit=easing((age-fx.orbitStart)/fx.orbitTime),lower=easing((age-fx.orbitStart)/(fx.lowerTime||10)),close=easing((age-fx.closeStart)/fx.closeTime),lift=easing((age-43)/5),el=(82+(fx.chessTilt-82)*pull+(fx.lowAngle-fx.chessTilt)*lower)*Math.PI/180,az=(18+fx.chessOrbit*pull+fx.orbitTurns*360*orbit)*Math.PI/180,dist=(.75+(fx.chessDistance-.75)*pull)*(1-close)+fx.closeDistance*close,target=[-.5*(1-pull)-.5*close,.04+.16*pull+close*(.8+lift*2.2),-.5*(1-pull)-2.8*close];return {position:[target[0]+dist*Math.sin(az)*Math.cos(el),target[1]+dist*Math.sin(el),target[2]+dist*Math.cos(az)*Math.cos(el)],target,fov:38}}
